/**
 * Sound profiles: which cues each game has, the file behind each cue and how
 * often it may sound. Every file is generated by `scripts/audio/generate.ts`
 * (original, deterministic synthesis; see public/audio/LICENSE.md).
 *
 * Profiles are presentation only. Nothing here reads or influences a round's
 * outcome: games call cues after the server has answered.
 */

export type GameSoundId = 'roulette' | 'dice' | 'mines' | 'crash' | 'blackjack' | 'limbo' | 'keno' | 'plinko' | 'hilo' | 'slots';

export interface CueSpec {
  /** Path under /audio/. */
  file: string;
  /** One-shot effect, or a loop that runs until stopped. */
  kind: 'effect' | 'loop';
  /** Which switch controls it: game effects, or the optional ambience. */
  bus: 'effects' | 'ambience';
  /** Relative level, 0–1. */
  gain: number;
  /** Minimum gap between two starts of this cue, in milliseconds. */
  cooldownMs: number;
  /** Most simultaneous voices of this cue; the oldest is cut when exceeded. */
  maxVoices: number;
}

const fx = (file: string, gain = 0.8, cooldownMs = 60, maxVoices = 2): CueSpec => ({ file, kind: 'effect', bus: 'effects', gain, cooldownMs, maxVoices });
/** A loop that belongs to the action (e.g. the ball rolling): follows the effects switch. */
const effectLoop = (file: string, gain = 0.5): CueSpec => ({ file, kind: 'loop', bus: 'effects', gain, cooldownMs: 0, maxVoices: 1 });
/** Background atmosphere: follows the ambience switch. */
const ambience = (file: string, gain = 0.5): CueSpec => ({ file, kind: 'loop', bus: 'ambience', gain, cooldownMs: 0, maxVoices: 1 });

