export type SoundProfiles = typeof SOUND_PROFILES;
export type CueOf<G extends GameSoundId> = keyof SoundProfiles[G] & string;

export const GAME_SOUND_IDS = Object.keys(SOUND_PROFILES) as GameSoundId[];

/** The profile a game id uses, or null for a game without sound. */
export function profileFor(gameId: string): GameSoundId | null {
  return (GAME_SOUND_IDS as string[]).includes(gameId) ? (gameId as GameSoundId) : null;
}

export function cueSpec(profile: GameSoundId, cue: string): CueSpec | null {
  const p = SOUND_PROFILES[profile] as Record<string, CueSpec>;
  return Object.prototype.hasOwnProperty.call(p, cue) ? p[cue]! : null;
}

export const AUDIO_BASE = '/audio/';
